<?php

/**
 * ONE-TIME deploy for quotation PDF header (text left, logo right + brand under logo).
 *
 * Upload to SAME folder as fix-server.php / check-files.php:
 *   public_html/tpi.turnkeyinfotech.live/public/deploy-quote-header.php
 * Open:
 *   https://tpi.turnkeyinfotech.live/deploy-quote-header.php?key=tpi-quote-2026
 * Then DELETE this file.
 */
header('Content-Type: text/plain; charset=utf-8');
if (($_GET['key'] ?? '') !== 'tpi-quote-2026') {
    http_response_code(403);
    echo "Forbidden\n";
    exit;
}

$base = dirname(__DIR__);
$files = [
    'resources/views/pdf/quotation.blade.php' => [
        'b64' => '',
        'bytes' => 9673,
    ],
    'app/Services/QuotationDocumentService.php' => [
        'b64' => '',
        'bytes' => 5795,
    ],
    'config/quotation.php' => [
        'b64' => '',
        'bytes' => 679,
    ],
    'public/images/quotation-logo.png' => [
        'b64' => '',
        'bytes' => 81132,
    ],
];

$ok = 0;
foreach ($files as $rel => $meta) {
    $path = $base.DIRECTORY_SEPARATOR.str_replace('/', DIRECTORY_SEPARATOR, $rel);
    $dir = dirname($path);
    if (! is_dir($dir) && ! @mkdir($dir, 0755, true) && ! is_dir($dir)) {
        echo "FAIL mkdir $dir\n";

        continue;
    }
    $bin = base64_decode($meta['b64'], true);
    if ($bin === false) {
        echo "FAIL decode $rel\n";

        continue;
    }
    $written = file_put_contents($path, $bin);
    if ($written === false) {
        echo "FAIL write $path\n";

        continue;
    }
    echo "OK $rel ($written bytes)\n";
    $ok++;
}

$viewCache = $base.'/storage/framework/views';
if (is_dir($viewCache)) {
    foreach (glob($viewCache.'/*.php') ?: [] as $f) {
        @unlink($f);
    }
    echo "OK cleared view cache\n";
}

$configCache = $base.'/bootstrap/cache/config.php';
if (is_file($configCache)) {
    @unlink($configCache);
    echo "OK cleared config cache\n";
}

echo "\nDone: $ok files written.\n";
echo "DELETE this file now: public/deploy-quote-header.php\n";
echo "Then re-download any quotation PDF.\n";
